-- Dataset integrity guards.
IF (SELECT COUNT(*) FROM @Paths WHERE scenario_code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025') <> 1888
BEGIN
    THROW 50011, 'Unexpected path row count for S49_IMAMOGLU_POLITICAL_SHOCK_2025.', 1;
END;

IF (SELECT COUNT(DISTINCT asset_code) FROM @Paths WHERE scenario_code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025') <> 59
BEGIN
    THROW 50012, 'Unexpected asset coverage for S49_IMAMOGLU_POLITICAL_SHOCK_2025.', 1;
END;

IF (SELECT MIN(day_index) FROM @Paths WHERE scenario_code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025') <> 0
   OR (SELECT MAX(day_index) FROM @Paths WHERE scenario_code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025') <> 49
BEGIN
    THROW 50013, 'Unexpected path day range for S49_IMAMOGLU_POLITICAL_SHOCK_2025.', 1;
END;

IF (SELECT COUNT(*) FROM @Paths WHERE scenario_code = 'S52_CHP_MUTLAK_BUTLAN_2025') <> 2301
BEGIN
    THROW 50011, 'Unexpected path row count for S52_CHP_MUTLAK_BUTLAN_2025.', 1;
END;

IF (SELECT COUNT(DISTINCT asset_code) FROM @Paths WHERE scenario_code = 'S52_CHP_MUTLAK_BUTLAN_2025') <> 59
BEGIN
    THROW 50012, 'Unexpected asset coverage for S52_CHP_MUTLAK_BUTLAN_2025.', 1;
END;

IF (SELECT MIN(day_index) FROM @Paths WHERE scenario_code = 'S52_CHP_MUTLAK_BUTLAN_2025') <> 0
   OR (SELECT MAX(day_index) FROM @Paths WHERE scenario_code = 'S52_CHP_MUTLAK_BUTLAN_2025') <> 52
BEGIN
    THROW 50013, 'Unexpected path day range for S52_CHP_MUTLAK_BUTLAN_2025.', 1;
END;

-- Guard: every scenario must already exist.
IF EXISTS (
    SELECT 1
    FROM @Paths p
    LEFT JOIN dbo.stress_scenarios s
        ON s.code = p.scenario_code
    WHERE s.id IS NULL
)
BEGIN
    THROW 50014, 'Stress path dataset contains an unknown scenario.', 1;
END;

-- Guard: every asset must already exist.
IF EXISTS (
    SELECT 1
    FROM @Paths p
    LEFT JOIN dbo.assets a
        ON a.asset_code = p.asset_code
    WHERE a.id IS NULL
)
BEGIN
    THROW 50015, 'Stress path dataset contains an unknown asset.', 1;
END;

-- Update existing path rows.
UPDATE target
SET
    target.path_date = source.path_date,
    target.close_value = source.close_value,
    target.impact = source.impact
FROM dbo.stress_scenario_asset_paths target
JOIN dbo.stress_scenarios scenario
    ON scenario.id = target.scenario_id
JOIN dbo.assets asset
    ON asset.id = target.asset_id
JOIN @Paths source
    ON source.scenario_code = scenario.code
   AND source.asset_code = asset.asset_code
   AND source.day_index = target.day_index;

-- Insert missing path rows.
INSERT INTO dbo.stress_scenario_asset_paths (
    scenario_id,
    asset_id,
    path_date,
    day_index,
    close_value,
    impact
)
SELECT
    scenario.id,
    asset.id,
    source.path_date,
    source.day_index,
    source.close_value,
    source.impact
FROM @Paths source
JOIN dbo.stress_scenarios scenario
    ON scenario.code = source.scenario_code
JOIN dbo.assets asset
    ON asset.asset_code = source.asset_code
WHERE NOT EXISTS (
    SELECT 1
    FROM dbo.stress_scenario_asset_paths existing
    WHERE existing.scenario_id = scenario.id
      AND existing.asset_id = asset.id
      AND existing.day_index = source.day_index
);

-- Final persisted-data validation.
IF (
    SELECT COUNT(*)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario
        ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025'
) <> 1888
BEGIN
    THROW 50016, 'Persisted path row count is invalid for S49_IMAMOGLU_POLITICAL_SHOCK_2025.', 1;
END;

IF (
    SELECT COUNT(DISTINCT path.asset_id)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario
        ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S49_IMAMOGLU_POLITICAL_SHOCK_2025'
) <> 59
BEGIN
    THROW 50017, 'Persisted path asset coverage is invalid for S49_IMAMOGLU_POLITICAL_SHOCK_2025.', 1;
END;

IF (
    SELECT COUNT(*)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario
        ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S52_CHP_MUTLAK_BUTLAN_2025'
) <> 2301
BEGIN
    THROW 50016, 'Persisted path row count is invalid for S52_CHP_MUTLAK_BUTLAN_2025.', 1;
END;

IF (
    SELECT COUNT(DISTINCT path.asset_id)
    FROM dbo.stress_scenario_asset_paths path
    JOIN dbo.stress_scenarios scenario
        ON scenario.id = path.scenario_id
    WHERE scenario.code = 'S52_CHP_MUTLAK_BUTLAN_2025'
) <> 59
BEGIN
    THROW 50017, 'Persisted path asset coverage is invalid for S52_CHP_MUTLAK_BUTLAN_2025.', 1;
END;

SET NOCOUNT OFF;
